"""Writes v5/INVENTORY.md from the code itself: modules, sizes, functions, synced stores, tests, outside hosts.
Run from v5/:  python3 tools/inventory.py"""
import re, glob, os
js = sorted(f for f in glob.glob('*.js') if f != 'sw.js'); out = ['# War Room · inventory (generated by tools/inventory.py; do not edit by hand)', '']
core = open('core.js').read(); ver = re.search(r"APP_VERSION = '([^']+)'", core).group(1)
singles = re.search(r"MERGE_SINGLES = \[([^\]]+)\]", core).group(1); maps = re.search(r"MERGE_MAPS = \[([^\]]+)\]", core).group(1)
out += [f'Version {ver}. {len(js)} script modules, {sum(os.path.getsize(f) for f in js)//1024} KB of JavaScript, {len(glob.glob("*.css"))} stylesheets, {len(glob.glob("lib/*.json"))} data files.', '']
out += ['## Synced stores', '', 'Single objects (field-level three-way merge): ' + singles.replace("'", ''), '', 'Maps of records (newest record wins): ' + maps.replace("'", ''), '', 'Separate cloud rows: call queue (`:queue`), caregiver bench (`:bench`), daily snapshots (`:snapN`).', '']
out += ['## Modules', '', '| File | KB | Functions | What it says it is |', '|---|---|---|---|']
for f in js:
    s = open(f).read(); n = len(re.findall(r'^(?:async )?function ', s, re.M)); m = re.search(r'/\*\s*(.*?)\*/', s, re.S); d = re.sub(r'\s+', ' ', m.group(1))[:150] if m else ''
    out.append(f'| {f} | {len(s)//1024} | {n} | {d.replace("|", "/")} |')
out += ['', '## Tests', '', '| Suite | Checks |', '|---|---|']
for t in sorted(glob.glob('tests/*.py')):
    out.append(f'| {os.path.basename(t)} | {len(re.findall(r"check\(", open(t).read()))} |')
hosts = sorted(set(re.findall(r'https://([a-z0-9.-]+\.[a-z]{2,})', ' '.join(open(f).read() for f in js))))
out += ['', '## Outside hosts named in code', '', ', '.join(h for h in hosts if not h.startswith('x.') and 'example' not in h), '']
open('INVENTORY.md', 'w').write('\n'.join(out)); print(len(out), 'lines')
